sys_ux_data_broker_transform.script:
function transform(input) {
    var kpiProperties = [
        'sam.foundation.current.users.kpi',
        'sam.foundation.current.company.kpi',
        'sam.foundation.current.location.kpi',
        'sam.foundation.current.costcenter.kpi',
        'sam.foundation.current.businessunit.kpi',
        'sam.foundation.current.department.kpi'
    ];

    function fetchKPIs(propertyName) {
        var kpis = [];
        var propertyValue = gs.getProperty(propertyName);
        if (propertyValue) {
            try {
                kpis = JSON.parse(propertyValue);
            } catch (e) {
                gs.info("Error parsing " + propertyName + ": " + e.message);
            }
        }
        return kpis;
    }

    function processKPIForVisualization(kpis, tableName) {
        var visualizationData = [];

        if (Array.isArray(kpis)) {
            kpis.forEach(function(kpi) {
                if (kpi.kpi && kpi.kpi.toLowerCase().indexOf('duplicate') !== -1) {
                    return; // Skip this KPI
                }
                if (kpi.description && kpi.description.toLowerCase().indexOf('duplicate') !== -1) {
                    return; // Skip this KPI
                }
                if (kpi.table && kpi.field) {


                    var queryCount = getqueryCount(kpi.table, kpi.field);

                    visualizationData.push({
                        "assignment_group": kpi.kpi || "(empty)",
                        "value": queryCount.toString()
                    });
                }
            });
        }

        // Wrap each result in an array
        return [
            [{
                "data": visualizationData,
                "metadata": {
                    "aggregateBy": 4,
                    "dataSourceLabel": tableName,
                    "eventData": {
                        "table": tableName.toLowerCase()
                    },
                    "format": {
                        "unitFormat": "{0}"
                    },
                    "groupBy": [{
                        "elements": visualizationData.map(function(item) {
                            return {
                                "eventData": {
                                    "query": "assignment_group=" + item.assignment_group
                                },
                                "id": gs.generateGUID(),
                                "label": item.assignment_group
                            };
                        }),
                        "fieldType": "reference",
                        "id": "assignment_group",
                        "label": "Assignment group",
                        "series": [{
                            "id": "value",
                            "label": tableName,
                            "type": "value"
                        }]
                    }],
                    "metricId": gs.generateGUID()
                }
            }]
        ];
    }

    function getqueryCount(tableName, query) {
        try {
            var gr = new GlideAggregate(tableName);
            if (query !== "none") {
                gr.addEncodedQuery(query);
            }
            gr.addAggregate('COUNT');
            gr.query();
            return gr.next() ? gr.getAggregate('COUNT') : 0;
        } catch (error) {
            gs.info("Error querying table " + tableName + ": " + error.message);
            return 0;
        }
    }

    // function getDuplicateCount(tableName, groupBy, query) {
    //     try {
    //         var gr = new GlideAggregate(tableName);
    //         gr.addEncodedQuery(query);
    //         gr.addAggregate('COUNT');
    //         gr.query();

    //         var duplicateCount = 0;
    //         while (gr.next()) {
    //             var count = parseInt(gr.getAggregate('COUNT'), 10);
    //             if (count > 1) {
    //                 duplicateCount++;
    //             }
    //         }
    //         return duplicateCount;
    //     } catch (error) {
    //         gs.log("Error querying table " + tableName + ": " + error.message);
    //         return 0;
    //     }
    // }

    // Process all KPIs and combine results
    var allResults = [];
    kpiProperties.forEach(function(property) {
        var kpis = fetchKPIs(property);
        var tableName = property.split('.').pop().replace('kpi', '').toUpperCase();
        var visualizationData = processKPIForVisualization(kpis, tableName);
        allResults = allResults.concat(visualizationData);
    });
    gs.info('testing valuesssssss' + JSON.stringify(allResults, null, 2));

    return allResults;
}
